/**
 * BREAKOUT MUSIC — JWT Verifier Factory
 *
 * Creates JWT verifier for custom token-based authentication
 * Uses the custom JWT verifier and Neon-backed session records.
 * Verifies tokens generated by POST /auth/login endpoint
 */

import type { JwtVerifier, CustomJwtConfig } from '../types/jwt';
import { CustomJwtVerifier } from './customJwtVerifier';

/** Create a verifier using the secret bound to this Worker environment. */
export async function getJwtVerifier(env: any): Promise<JwtVerifier> {
  const jwtSecret = typeof env?.JWT_SECRET === 'string' ? env.JWT_SECRET : '';
  if (!jwtSecret.trim()) {
    throw new Error('Authentication service is not configured');
  }

  const config: CustomJwtConfig = {
    signingKey: jwtSecret,
    algorithm: 'HS256',
    issuer: 'breakout-music-api',
    audience: 'breakout-music',
    clockSkew: 60,
  };

  return new CustomJwtVerifier(config);
}
